export function estimateOutputBytes(output: unknown): number {
  if (output === undefined || output === null) return 0;
  try {
    return typeof output === 'string'
      ? output.length
      : JSON.stringify(output).length;
  } catch {
    return 0;
  }
}

export function normalizeOutput(output: unknown): unknown {
  if (typeof output === 'string') {
    try {
      return JSON.parse(output);
    } catch {
      return output;
    }
  }
  return output;
}

export function resolveAssetWithinBase(
  base: string,
  requestedPath: string,
): string | undefined {
  const target = path.resolve(base, '.' + path.sep + requestedPath);
  if (!isPathWithinRoot(base, target)) {
    return undefined;
  }
  let realTarget: string;
  try {
    realTarget = fs.realpathSync(target);
  } catch {
    return undefined;
  }
  if (!isPathWithinRoot(base, realTarget)) {
    return undefined;
  }
  try {
    const stat = fs.statSync(realTarget);
    if (!stat.isFile()) return undefined;
    if (stat.nlink !== 1) return undefined;
    return realTarget;
  } catch {
    return undefined;
  }
}

export function resolveStaticPreviewAssetBase(args: {
  assetBase: string | undefined;
  projectContext: ProjectContext;
}): string | undefined {
  if (!args.assetBase) return undefined;
  if (args.projectContext.kind !== 'fresh') return undefined;
  let workspace: string;
  let resolved: string;
  try {
    const wsStat = fs.lstatSync(args.projectContext.workspacePath);
    if (wsStat.isSymbolicLink()) {
      log.warn(
        `Static preview workspacePath ${args.projectContext.workspacePath} is a symlink — refusing assetBase`,
      );
      return undefined;
    }
    const realWorkspaceRoot = fs.realpathSync(
      args.projectContext.workspaceRoot,
    );
    workspace = fs.realpathSync(args.projectContext.workspacePath);
    if (!isPathStrictlyInsideRoot(realWorkspaceRoot, workspace)) {
      log.warn(
        `Static preview workspacePath ${workspace} is not a strict descendant of workspaceRoot ${realWorkspaceRoot} — refusing assetBase`,
      );
      return undefined;
    }
    const candidate = path.isAbsolute(args.assetBase)
      ? args.assetBase
      : path.join(workspace, args.assetBase);
    resolved = fs.realpathSync(candidate);
  } catch {
    log.warn(
      `Static preview assetBase ${args.assetBase} could not be resolved — ignoring`,
    );
    return undefined;
  }
  if (!isPathWithinRoot(workspace, resolved)) {
    log.warn(
      `Static preview assetBase ${args.assetBase} escapes workspace ${workspace} — ignoring`,
    );
    return undefined;
  }
  try {
    const stat = fs.statSync(resolved);
    if (!stat.isDirectory()) {
      log.warn(
        `Static preview assetBase ${resolved} is not a directory — ignoring`,
      );
      return undefined;
    }
    return resolved;
  } catch {
    log.warn(`Static preview assetBase ${resolved} does not exist — ignoring`);
    return undefined;
  }
}

export function parseStaticPreviewOutput(
  output: unknown,
): { html: string; assetBase?: string } | null {
  if (!output || typeof output !== 'object') return null;
  const html = (output as { html?: unknown }).html;
  if (typeof html !== 'string' || html.trim().length === 0) return null;
  const css = (output as { css?: unknown }).css;
  const js = (output as { js?: unknown }).js;
  const assetBase = (output as { assetBase?: unknown }).assetBase;
  return {
    html: buildStaticPreviewDocument({
      html,
      css: typeof css === 'string' ? css : undefined,
      js: typeof js === 'string' ? js : undefined,
    }),
    ...(typeof assetBase === 'string' && assetBase.length > 0
      ? { assetBase }
      : {}),
  };
}

export function buildStaticPreviewDocument(input: {
  html: string;
  css?: string;
  js?: string;
}): string {
  const style = input.css ? `<style>\n${input.css}\n</style>` : '';
  const script = input.js ? `<script>\n${input.js}\n</script>` : '';
  if (/<!doctype html>|<html[\s>]/i.test(input.html)) {
    let doc = input.html;
    if (style) {
      if (/<\/head>/i.test(doc)) {
        doc = doc.replace(/<\/head>/i, () => `${style}\n</head>`);
      } else {
        doc += `\n${style}`;
      }
    }
    if (script) {
      if (/<\/body>/i.test(doc)) {
        doc = doc.replace(/<\/body>/i, () => `${script}\n</body>`);
      } else {
        doc += `\n${script}`;
      }
    }
    return doc;
  }
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    ${style}
  </head>
  <body>
${input.html}
    ${script}
  </body>
</html>`;
}

export function countDiffFiles(diff: string): number {
  return (diff.match(/^diff --git /gm) ?? []).length;
}

export function countWorktreeFiles(destinationPath: string): number {
  let count = 0;
  const walk = (dir: string): void => {
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      if (MATERIALIZE_EXCLUDE.has(entry.name)) continue;
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(full);
      else if (entry.isFile()) count += 1;
    }
  };
  walk(destinationPath);
  return count;
}

export const MATERIALIZE_EXCLUDE = new Set([
  'node_modules',
  '.git',
  '.rivet',
  'dist',
  '.next',
  '.cache',
  '.vite',
]);

export const STATIC_PREVIEW_HISTORY_EXCLUDE = new Set([
  ...MATERIALIZE_EXCLUDE,
  '.rivet',
]);
export const STATIC_PREVIEW_HISTORY_FILE_EXTENSIONS = new Set([
  ...ALLOWED_INERT_ASSET_EXTENSIONS,
  '.css',
  '.htm',
  '.html',
  '.js',
]);

export function copyStaticPreviewDirectory(src: string, dest: string): void {
  fs.mkdirSync(dest, { recursive: true });
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(src, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    if (
      entry.name.startsWith('.') ||
      STATIC_PREVIEW_HISTORY_EXCLUDE.has(entry.name)
    ) {
      continue;
    }
    const from = path.join(src, entry.name);
    const to = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      copyStaticPreviewDirectory(from, to);
    } else if (entry.isFile()) {
      const extension = path.extname(entry.name).toLowerCase();
      if (!STATIC_PREVIEW_HISTORY_FILE_EXTENSIONS.has(extension)) continue;
      let stat: fs.Stats;
      try {
        stat = fs.statSync(from);
      } catch {
        continue;
      }
      if (!stat.isFile() || stat.nlink !== 1) continue;
      fs.mkdirSync(path.dirname(to), { recursive: true });
      fs.copyFileSync(from, to);
    }
  }
}

export const defaultInstallDependencies = async (
  worktreePath: string,
  options?: { workspaceRoot: string; force?: boolean; signal?: AbortSignal },
): Promise<void> => {
  await previewDependencies.prepare({
    cwd: worktreePath,
    workspaceRoot: options?.workspaceRoot ?? worktreePath,
    force: options?.force,
    signal: options?.signal,
  });
};

export const buildServeRecipeFromResolved = (
  snapshotRoot: string,
  dev: {
    cwd: string;
    cmd: string;
    args: string[];
    env: Record<string, string>;
  },
  port: number,
): DevServerRecipe => {
  const portPattern = new RegExp(`(?<![0-9])${port}(?![0-9])`, 'g');
  const sub = (value: string) => value.replace(portPattern, '${PORT}');
  const relativeCwd = path.relative(snapshotRoot, dev.cwd);
  return {
    cwd: relativeCwd === '' ? '.' : relativeCwd,
    cmd: dev.cmd,
    argsTemplate: dev.args.map(sub),
    envTemplate: Object.fromEntries(
      Object.entries(dev.env).map(([key, value]) => [key, sub(value)]),
    ),
  };
};

export const canInstallWithoutTouchingHost = (cwd: string): boolean => {
  try {
    return !fs.lstatSync(path.join(cwd, 'node_modules')).isSymbolicLink();
  } catch {
    return true;
  }
};

export const assertDevScriptExists = (
  cwd: string,
  scriptName: string,
): void => {
  let scripts: Record<string, unknown> | undefined;
  try {
    const raw = fs.readFileSync(path.join(cwd, 'package.json'), 'utf8');
    const parsed: unknown = JSON.parse(raw);
    if (parsed && typeof parsed === 'object' && 'scripts' in parsed) {
      const candidate = (parsed as { scripts?: unknown }).scripts;
      if (candidate && typeof candidate === 'object') {
        scripts = candidate as Record<string, unknown>;
      }
    }
  } catch {
    return;
  }
  if (scripts && typeof scripts[scriptName] === 'string') return;
  const available = Object.keys(scripts ?? {});
  throw new DevServerStartError({
    message:
      `package.json at ${cwd} has no "${scriptName}" script` +
      (available.length ? ` (available: ${available.join(', ')})` : ''),
    reason: 'missing_dev_script',
    portInUse: false,
    detail: available.length
      ? `available scripts: ${available.join(', ')}`
      : '',
  });
};

export function synthesizeUnifiedBriefBody(
  prompt: string,
  index: number,
  total: number,
): string {
  const trimmed = prompt.trim().replace(/\s+/g, ' ').slice(0, 200);
  const intent = trimmed.length > 0 ? trimmed : 'Create this variant';
  if (total <= 1) return intent;
  const focus =
    FALLBACK_DIRECTION_FOCI[
      (Math.max(index, 1) - 1) % FALLBACK_DIRECTION_FOCI.length
    ];
  return `${intent} Direction ${index} of ${total}: ${focus}`;
}
